import {managedScheduleSchema} from './managed-triggers.js';
import {nativeModelChoice} from './native-model-choice.js';
import {developmentSchema} from './managed-development-contract.js';
import {currentHumanRequest} from './task-envelope.js';
import {hash} from './store.js';
export function registerManagedTools(g,register){
 const str={type:'string'},policy={type:'object',properties:{provider:str,model:str,reasoningEffort:str},required:['provider','model'],additionalProperties:false};
 const properties={schedule:managedScheduleSchema,task_id:str,expected_revision:{type:'integer',minimum:1},role:{type:'string',enum:['cloud']},cwd:str,development:{anyOf:[developmentSchema,{type:"null"}],description:"Required output agreement for ALL file tasks (reports, JSONL, data and code): use workspace delivery with real checks and relative artifact paths. Explicit null only for genuinely no-file tasks; omission is rejected."},scope:{type:'string',maxLength:3000},model_query:{type:'string',description:'User-written model name only; omit for saved task choice or cloud default.'},provider_hint:str,search:{type:'object',properties:{scope:{type:'string',maxLength:1000}},required:['scope'],additionalProperties:false},period_seconds:{type:'integer',minimum:60,maximum:31622400},end_at:{type:'integer',minimum:1}};
 const start=async(a,e)=>{
  const model_policy=await nativeModelChoice(g,a,e);
  if(!Object.hasOwn(a,'development')||a.development===undefined)throw Error('TASK_OUTPUT_CONTRACT_REQUIRED: file tasks need development.artifacts/checks; use explicit null only when no file deliverable exists');
  const {development,...rest}=a;
  return g.call('execution_start',{...rest,...(development===null?{}:{development}),model_policy,role:'cloud',event_id:'native-execution:'+hash(g.c.role+':'+e.agent.id+':'+currentHumanRequest(e.agent).message_id+':'+e.callId)});
 };
 register('task_execute','Start/queue the saved explicit user task on CLOUD. No approval ID, IM permission, model request cap, fixed activity timeout or permission TTL. Omit model_query for the configured CLOUD default or saved explicit task choice; never invent a model name or resolve the entry model. Only quote a model name actually specified by the user. Search scope enables the already configured auxiliary route, without per-task model consent or a request sublimit. cwd is a working start, not a file sandbox. Native tools follow cloud account capabilities and user goal/restrictions. Optional end_at is ONLY an explicit business deadline, never an invented default. development is REQUIRED for every task: ALL file deliverables (including reports, research and JSONL) must list artifacts plus actual checks, workspace needs no Git; explicit null only for no-file tasks. Missing output agreement is an error, not a successfully queued file task; no per-artifact registration needed. Use schedule for explicit once/interval/weekly/dependency/named-signal plans; do not invent a deadline or business round count. schedule cannot combine with period_seconds. Followup does not fire a named signal. Periodic tasks reuse session, skip missed rounds, never silently switch model. Pause/stop via task_lifecycle. Historical capped/local contracts are not migrated or restarted.',properties,['task_id','expected_revision','cwd','development'],start);
 register('task_execution_prepare','Compatibility name for task_execute on NEW cloud-autonomous tasks: this now queues execution immediately, not an approval proposal. Prefer task_execute. Existing historical approval records remain read-only and are never upgraded implicitly.',properties,['task_id','expected_revision','cwd','development'],start);
}
